  "interactiveHelp.ended": "Interaktivní nápověda je vypnutá",
  "shortcuts.interactiveHelp": "Zapnout nebo vypnout interaktivní nápovědu",
  "installHint.chromium": "Použijte ikonu vpravo v adresním řádku nebo nabídku prohlížeče „Nainstalovat jako aplikaci“.",
  "installHint.safariMac": "V Safari: Soubor → „Přidat do Docku“.",
  "installHint.ios": "V Safari: ikona Sdílet → „Přidat na plochu“.",
  "installHint.firefox": "Firefox neumí instalovat aplikace. Layerling zde přesto funguje bez internetu v kartě.",
  "welcome.moreLanguagesTitle": "Jazyk",
  "welcome.moreLanguagesBody": "program i jeho návod mluví anglicky, německy a dalšími 17 jazyky; seznam jazyků je úplně vpravo nahoře a v nastavení na úvodní stránce.",
  "welcome.moreOfflineTitle": "Funguje bez internetu",
  "welcome.moreOfflineBody": "po první návštěvě se layerling spustí i bez internetu. Nainstalujte jej jako běžný program; projekty zůstávají na vašem počítači.",
  "welcome.moreAiTitle": "Modelování s AI",
  "welcome.moreAiBody": "přes rozhraní MCP může AI asistent vytvářet a upravovat tvary v editoru. Vyžaduje to vlastní spuštěnou kopii (npm run dev nebo Docker obraz); na layerling.com je připojení AI vypnuté.",
  "welcome.morePointsTitle": "Referenční body",
  "welcome.moreSearchTitle": "Vyhledávání příkazů",
  "welcome.moreSimplifyTitle": "Zjednodušení polygonové sítě",
  "welcome.moreSimplifyBody": "Importovaný model s velkým počtem trojúhelníků lze zjednodušit pomocí posuvníku a porovnání před a po. Řezání, slučování i přesouvání pak běží plynuleji.",
  "welcome.moreHistoryTitle": "Historie",
  "welcome.moreLookTitle": "Vzhled podle vás",
  "welcome.moreLookBody": "V nastavení upravíte pozadí, pracovní rovinu, šipky os X, Y a Z, hrany těles, barvy náčrtu, kontrast, stíny i směr světla. Tmavá tělesa tak nesplývají. Na pomalejším počítači rychlý režim vypne náročné efekty jedním přepínačem.",
  "welcome.moreHistoryBody": "posuvníkem prohlížejte předchozí stavy projektu beze změny současného modelu. Vybraný stav můžete exportovat nebo z něj vytvořit nový projekt.",
  "welcome.moreSearchBody": "Stiskněte Ctrl+K a zadejte název nástroje, tvaru nebo příkazu. Vyhledávání rozumí českým názvům i anglickým a německým výrazům a zobrazuje klávesové zkratky. Najde také tělesa podle názvu.",
  "welcome.morePointsBody": "pravým tlačítkem na tělese označte jeho střed, rohy nebo středy hran referenčními body, které se netisknou. Tvary se k nim přichytávají, takže například otvor umístíte přesně do středu jiného dílu.",
  "welcome.videosTitle": "Videa o layerlingu",
  "welcome.videosHint": "Videa vytvořili jiní autoři. Odkazy otevřou YouTube v nové kartě; před kliknutím se z něj nic nenačítá.",
  "welcome.help": "V editoru najdete v části Nápověda stručného průvodce a seznam klávesových zkratek. „Nahlásit chybu“ v zápatí uloží projekt s podklady pro hlášení na fóru nebo GitHubu.",
  "welcome.guideLink": "Otevřít úplnou příručku s obrázky",
  "welcome.guideUrl": "/prirucka/index.html",
  "guide.helpLink": "Přečíst v uživatelské příručce",
