  "guide.edges.offset": "Odsazení posune každou plochu tělesa o stejnou vzdálenost ven nebo dovnitř. Zvětši kopii a ponech ji jako díru, získáš vůli lícovaného spoje; nebo těleso zmenši pro čep, který má zapadnout do díry. Tělesa, která jsou jen trojúhelníková síť, jdou často odsadit jen těžko.",
