  "deleteFace.help": "Klikněte na plochy, které mají zmizet; dalším kliknutím plochu z výběru odeberete. Okolní plochy se rozšíří, až se mezera uzavře: zaoblení, otvor nebo výstupek zmizí a těleso zůstane přesné.",
